ROOT = Path(__file__).resolve().parent

# The supplied workbook is embedded so the deployed app does not depend on
# the user manually placing the XLSM beside the Python file.  If an external
# workbook with the expected name is present, it is preferred; otherwise the
# embedded copy is extracted to a local temporary/cache directory.
_EMBEDDED_WORKBOOK_ZLIB_B64 = """"""
WORKBOOK_CANDIDATES = [
    ROOT / "Kitchen cutting list 25826(1).xlsm",
    ROOT / "Kitchen cutting list 25826.xlsm",
]

@st.cache_resource(show_spinner=False)
def find_workbook():
    # 1. Exact filenames beside the app.
    for p in WORKBOOK_CANDIDATES:
        if p.is_file():
            return p

    # 2. Be tolerant of renamed/downloaded XLSM files.  This is useful when
    #    browsers turn spaces or parentheses into a different local filename.
    for p in sorted(ROOT.glob("*.xlsm")):
        if p.is_file():
            return p

    # 3. Fall back to the embedded source workbook.
    embedded_dir = Path(tempfile.gettempdir()) / "furniture_cutting_embedded"
    embedded_dir.mkdir(parents=True, exist_ok=True)
    embedded_path = embedded_dir / "Kitchen cutting list 25826(1).xlsm"
    if not embedded_path.exists() or embedded_path.stat().st_size == 0:
        import base64
        import zlib
        embedded_path.write_bytes(zlib.decompress(base64.b64decode(_EMBEDDED_WORKBOOK_ZLIB_B64)))
    return embedded_path


@st.cache_resource(show_spinner=False)
def prepare_template(workbook_path: str, generator: str):
    src = openpyxl.load_workbook(workbook_path, data_only=False, keep_vba=False)
    if generator == "Kitchen Base Cabinet":
        sheets = ["Kitchen cab", "detailed c list"]
    else:
        sheets = [generator]

    out_dir = Path(tempfile.gettempdir()) / "furniture_cutting_templates"
    out_dir.mkdir(parents=True, exist_ok=True)
    safe = re.sub(r"[^A-Za-z0-9]+", "_", generator).strip("_")
    out = out_dir / f"{safe}.xlsx"
    if not out.exists():
        new = openpyxl.Workbook()
        new.remove(new.active)
        for name in sheets:
            ws = src[name]
            nw = new.create_sheet(name)
            for row in ws.iter_rows():
                for cell in row:
                    nw.cell(cell.row, cell.column).value = cell.value
        if generator == "Kitchen Base Cabinet":
            for name in ["BBackpanelthick", "BDepth", "BHight", "Bmaterial", "Bthick", "maxcut", "Skirting_Hight", "Whight"]:
                if name in src.defined_names:
                    dn = src.defined_names[name]
                    new.defined_names.add(openpyxl.workbook.defined_name.DefinedName(name, attr_text=dn.attr_text))
        new.save(out)
    return out


def _scalar(solution, sheet, cell):
    sheet_u = sheet.upper()
    suffix = "!" + cell.upper()
    for key, value in solution.items():
        if sheet_u in str(key).upper() and str(key).upper().endswith(suffix):
            try:
                x = value.value
                return x[0][0] if x and x[0] else None
            except Exception:
                return None
    return None


def _clean_value(v):
    if v is None:
        return None
    s = str(v)
    if any(e in s for e in ["#DIV/0!", "#VALUE!", "#REF!", "#NAME?", "#N/A"]):
        return None
    return v


def run_formula_generator(generator, updates, output_start, output_end, kitchen=False):
    workbook = find_workbook()
    if workbook is None:
        raise FileNotFoundError(
            "Put 'Kitchen cutting list 25826(1).xlsm' beside this app before running it."
        )
    template = prepare_template(str(workbook), generator if not kitchen else "Kitchen Base Cabinet")
    with tempfile.NamedTemporaryFile(suffix=".xlsx", delete=False) as f:
        run_path = Path(f.name)
    wb = openpyxl.load_workbook(template, data_only=False)
    for sheet, cells in updates.items():
        ws = wb[sheet]
        for cell, value in cells.items():
            ws[cell] = value
    wb.save(run_path)

    model = formulas.ExcelModel().loads(str(run_path)).finish()
    solution = model.calculate()
    sheet = "detailed c list" if kitchen else generator
    rows = []
    for r in range(output_start, output_end + 1):
        item = _clean_value(_scalar(solution, sheet, f"B{r}"))
        if item in (None, "", 0):
            continue
        qty_col = "F" if kitchen else "E"
        qty = _clean_value(_scalar(solution, sheet, f"{qty_col}{r}"))
        qty_num = pd.to_numeric(qty, errors="coerce") if qty is not None else 0
        if pd.isna(qty_num) or float(qty_num) <= 0:
            continue
        if kitchen:
            row = {
                "Item": item,
                "Length": _clean_value(_scalar(solution, sheet, f"C{r}")),
                "Width": _clean_value(_scalar(solution, sheet, f"D{r}")),
                "Thickness": _clean_value(_scalar(solution, sheet, f"E{r}")),
                "Qty": qty_num,
                "Right Exposed": _clean_value(_scalar(solution, sheet, f"G{r}")),
                "Left Exposed": _clean_value(_scalar(solution, sheet, f"H{r}")),
                "Specification": _clean_value(_scalar(solution, sheet, f"I{r}")),
                "Material": _clean_value(_scalar(solution, sheet, f"Q{r}")),
                "Edge L1": _clean_value(_scalar(solution, sheet, f"R{r}")),
                "Edge L2": _clean_value(_scalar(solution, sheet, f"S{r}")),
                "Edge W1": _clean_value(_scalar(solution, sheet, f"T{r}")),
                "Edge W2": _clean_value(_scalar(solution, sheet, f"U{r}")),
            }
        else:
            row = {
                "Item": item,
                "Length": _clean_value(_scalar(solution, sheet, f"C{r}")),
                "Width": _clean_value(_scalar(solution, sheet, f"D{r}")),
                "Qty": qty_num,
                "Specification": _clean_value(_scalar(solution, sheet, f"F{r}")),
                "Material": _clean_value(_scalar(solution, sheet, f"H{r}")),
                "Edge L1": _clean_value(_scalar(solution, sheet, f"I{r}")),
                "Edge L2": _clean_value(_scalar(solution, sheet, f"J{r}")),
                "Edge W1": _clean_value(_scalar(solution, sheet, f"K{r}")),
                "Edge W2": _clean_value(_scalar(solution, sheet, f"L{r}")),
            }
        rows.append(row)
    try:
        run_path.unlink(missing_ok=True)
    except Exception:
        pass
    return pd.DataFrame(rows)


def optional_int(label, value, key, minimum=0, maximum=100):
    blank = st.checkbox(f"{label}: blank/default", value=value is None, key=key + "_blank")
    if blank:
        return None
    return int(st.number_input(label, min_value=minimum, max_value=maximum, value=int(value or minimum), key=key))


def show_results(cut_list, title="Cutting list"):
    if cut_list is None or cut_list.empty:
        st.warning("The workbook produced no positive-quantity cutting rows for these inputs.")
        return
    st.markdown(f"### {title}")
    a,b,c = st.columns(3)
    a.metric("Cutting rows", len(cut_list))
    b.metric("Total pieces", int(pd.to_numeric(cut_list["Qty"], errors="coerce").fillna(0).sum()))
    c.metric("Distinct materials", int(cut_list.get("Material", pd.Series(dtype=str)).dropna().astype(str).nunique()))
    st.dataframe(cut_list, use_container_width=True, hide_index=True)
    st.download_button("⬇️ Download CSV", cut_list.to_csv(index=False).encode("utf-8"), "cutting_list.csv", "text/csv", use_container_width=True)


